real_t algorithm_histogram(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    int outer_limit = iterations / 4 + 1;

    for (int nl = 0; nl < outer_limit; nl++) {
        // Reset x array to 0.0
        for (Index_type i = 0; i < 256; ++i) x[i] = 0.0;

        // Optimized histogram accumulation
        #if defined(__riscv_vector)
        size_t vl;
        for (Index_type i = 0; i < LEN_1D; ) {
            vl = __riscv_vsetvl_e64m1(LEN_1D - i);
            vuint64m1_t v_idx = __riscv_vle64_v_u64m1((const unsigned long *)&idx_list[i], vl);

            // Since __riscv_vextract is not a standard intrinsic in all RVV toolchains,
            // and we must handle potential collisions for the histogram,
            // we use a temporary scalar array to extract the vector elements.
            unsigned long indices[vl];
            __riscv_vse64_v_u64m1(indices, v_idx, vl);

            for (size_t j = 0; j < vl; j++) {
                x[indices[j]] += 1.0;
            }
            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            x[idx_list[i]] += 1.0;
        }
        #endif

        dummy(x, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

