        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e32m8(LEN_1D - i);
            vfloat32m8_t vec_x = __riscv_vle32_v_f32m8(&x[i], vl);
            __riscv_vse32_v_f32m8(&y[i], vec_x, vl);
            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = x[i];
        }
#endif
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

