real_t algorithm_memset(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t val = 1.42;

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        Index_type i = 0;
        // The intrinsic __riscv_vse32_v_f32m1 takes (pointer, vector, vl)
        // We need to set the vector value inside the loop or ensure it matches the current vl
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e32m1(LEN_1D - i);
            vfloat32m1_t v_val = __riscv_vfmv_v_f_f32m1(vl, val);
            __riscv_vse32_v_f32m1(&x[i], v_val, vl);
            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            x[i] = val;
        }
        #endif
        dummy(x, NULL, NULL, NULL, NULL, val);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

