real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;

    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        int i = 0;
        vfloat32m1_t v_acc = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());

        for (; i < LEN_1D; ) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);
            vfloat32m1_t v_x = __riscv_vle32_v_f32m1(&x[i], vl);
            v_acc = __riscv_vfadd_vv_f32m1(v_acc, v_x, vl);
            i += vl;
        }

        // Correct intrinsic for reduction sum is __riscv_vfredusum_vs
        // It takes a scalar vector (v0) and the vector to reduce.
        vfloat32m1_t v_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        vfloat32m1_t v_res = __riscv_vfredusum_vs_f32m1(v_acc, v_zero, __riscv_vsetvlmax_e32m1());
        s = (real_t)__riscv_vfmv_f_s_f32m1_f32(v_res);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) s += x[i];
        #endif

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
    // Cast to long long or use 1LL to prevent integer overflow before floating point division
    y[0] = acc / (real_t)((long long)iterations * (long long)LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

