real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        real_t scan_var = 0.0;
        Index_type i = 0;

#if defined(__riscv_vector)
        /* 
         * Exclusive scan: y[i] = sum(x[0...i-1]).
         * To vectorize this, we use a block-based approach:
         * 1. Compute the local inclusive scan of a vector block.
         * 2. Add the carry (scan_var) from the previous block to all elements.
         * 3. Shift the inclusive scan to make it exclusive.
         * 4. Update scan_var with the total sum of the block.
         */
        size_t vlmax = __riscv_vsetvlmax_e32m8();
        for (; i <= LEN_1D - vlmax; i += vlmax) {
            vfloat32m8_t vx = __riscv_vle32_v_f32m8(&x[i], vlmax);

            // Compute inclusive scan of the current block
            // Since RVV 1.0 doesn't have a native vscan, we use a 
            // recursive doubling (Kogge-Stone) approach for the block.
            vfloat32m8_t vsum = vx;
            for (int shift = 1; shift < vlmax; shift <<= 1) {
                vfloat32m8_t vshifted = __riscv_vslide1up_v_f32m8(0.0f, vsum, vlmax);
                // We only need to add where the shift is valid
                vsum = __riscv_vfadd_vv_f32m8(vsum, vshifted, vlmax);
            }

            // Now vsum contains the inclusive scan of the block.
            // y[i...i+vlmax-1] = scan_var + inclusive_scan(x[i...i+vlmax-2])
            // The first element of y is just scan_var.
            vfloat32m8_t v_carry = __riscv_vfmv_v_f_f32m8(scan_var, vlmax);
            vfloat32m8_t vy = __riscv_vfadd_vv_f32m8(vsum, v_carry, vlmax);

            // Shift right by 1 to make it exclusive
            vfloat32m8_t v_exclusive = __riscv_vslide1up_v_f32m8(scan_var, vy, vlmax);

            __riscv_vse32_v_f32m8(&y[i], v_exclusive, vlmax);

            // Update scan_var for the next block: scan_var += sum of current block
            // The last element of the inclusive scan (vsum) is the total sum of the block.
            real_t block_sum;
            __riscv_vse32_v_f32m1(&block_sum, __riscv_vget_v_f32m1_f32m8(vsum, vlmax - 1), 1);
            scan_var += block_sum;
        }
#endif

        // Handle remaining elements
        for (; i < LEN_1D; ++i) {
            y[i] = scan_var;
            scan_var += x[i];
        }
        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

