real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-2f;
    int nl_limit = iterations / 4 + 1;

    for (int nl = 0; nl < nl_limit; nl++) {
        int i = 0;
#if defined(__riscv_vector)
        for (; i <= APPS_N1D - 1; ) {
            size_t vl = __riscv_vsetvl_e32m8(APPS_N1D - i);

            vfloat32m8_t vx1 = __riscv_vle32_v_f32m8(&apps_x1[i], vl);
            vfloat32m8_t vx2 = __riscv_vle32_v_f32m8(&apps_x2[i], vl);
            vfloat32m8_t vx3 = __riscv_vle32_v_f32m8(&apps_x3[i], vl);
            vfloat32m8_t vx4 = __riscv_vle32_v_f32m8(&apps_x4[i], vl);

            vfloat32m8_t vy1 = __riscv_vle32_v_f32m8(&apps_y1[i], vl);
            vfloat32m8_t vy2 = __riscv_vle32_v_f32m8(&apps_y2[i], vl);
            vfloat32m8_t vy3 = __riscv_vle32_v_f32m8(&apps_y3[i], vl);
            vfloat32m8_t vy4 = __riscv_vle32_v_f32m8(&apps_y4[i], vl);

            vfloat32m8_t vfx1 = __riscv_vle32_v_f32m8(&apps_fx1[i], vl);
            vfloat32m8_t vfx2 = __riscv_vle32_v_f32m8(&apps_fx2[i], vl);
            vfloat32m8_t vfx3 = __riscv_vle32_v_f32m8(&apps_fx3[i], vl);
            vfloat32m8_t vfx4 = __riscv_vle32_v_f32m8(&apps_fx4[i], vl);

            vfloat32m8_t vfy1 = __riscv_vle32_v_f32m8(&apps_fy1[i], vl);
            vfloat32m8_t vfy2 = __riscv_vle32_v_f32m8(&apps_fy2[i], vl);
            vfloat32m8_t vfy3 = __riscv_vle32_v_f32m8(&apps_fy3[i], vl);
            vfloat32m8_t vfy4 = __riscv_vle32_v_f32m8(&apps_fy4[i], vl);

            vfloat32m8_t vptiny = __riscv_vfmv_v_f_f32m8(ptiny, vl);

            // xi = half * (x1 + x2 - x3 - x4)
            vfloat32m8_t vxi = __riscv_vfadd_vv_f32m8(vx1, vx2, vl);
            vxi = __riscv_vfsub_vv_f32m8(vxi, vx3, vl);
            vxi = __riscv_vfsub_vv_f32m8(vxi, vx4, vl);
            vxi = __riscv_vfmul_vf_f32m8(vxi, half, vl);

            // xj = half * (x2 + x3 - x4 - x1)
            vfloat32m8_t vxj = __riscv_vfadd_vv_f32m8(vx2, vx3, vl);
            vxj = __riscv_vfsub_vv_f32m8(vxj, vx4, vl);
            vxj = __riscv_vfsub_vv_f32m8(vxj, vx1, vl);
            vxj = __riscv_vfmul_vf_f32m8(vxj, half, vl);

            // yi = half * (y1 + y2 - y3 - y4)
            vfloat32m8_t vyi = __riscv_vfadd_vv_f32m8(vy1, vy2, vl);
            vyi = __riscv_vfsub_vv_f32m8(vyi, vy3, vl);
            vyi = __riscv_vfsub_vv_f32m8(vyi, vy4, vl);
            vyi = __riscv_vfmul_vf_f32m8(vyi, half, vl);

            // yj = half * (y2 + y3 - y4 - y1)
            vfloat32m8_t vyj = __riscv_vfadd_vv_f32m8(vy2, vy3, vl);
            vyj = __riscv_vfsub_vv_f32m8(vyj, vy4, vl);
            vyj = __riscv_vfsub_vv_f32m8(vyj, vy1, vl);
            vyj = __riscv_vfmul_vf_f32m8(vyj, half, vl);

            // fxi = half * (fx1 + fx2 - fx3 - fx4)
            vfloat32m8_t vfxi = __riscv_vfadd_vv_f32m8(vfx1, vfx2, vl);
            vfxi = __riscv_vfsub_vv_f32m8(vfxi, vfx3, vl);
            vfxi = __riscv_vfsub_vv_f32m8(vfxi, vfx4, vl);
            vfxi = __riscv_vfmul_vf_f32m8(vfxi, half, vl);

            // fxj = half * (fx2 + fx3 - fx4 - fx1)
            vfloat32m8_t vfxj = __riscv_vfadd_vv_f32m8(vfx2, vfx3, vl);
            vfxj = __riscv_vfsub_vv_f32m8(vfxj, vfx4, vl);
            vfxj = __riscv_vfsub_vv_f32m8(vfxj, vfx1, vl);
            vfxj = __riscv_vfmul_vf_f32m8(vfxj, half, vl);

            // fyi = half * (fy1 + fy2 - fy3 - fy4)
            vfloat32m8_t vfy_i = __riscv_vfadd_vv_f32m8(vfy1, vfy2, vl);
            vfy_i = __riscv_vfsub_vv_f32m8(vfy_i, vfy3, vl);
            vfy_i = __riscv_vfsub_vv_f32m8(vfy_i, vfy4, vl);
            vfy_i = __riscv_vfmul_vf_f32m8(vfy_i, half, vl);

            // fyj = half * (fy2 + fy3 - fy4 - fy1)
            vfloat32m8_t vfy_j = __riscv_vfadd_vv_f32m8(vfy2, vfy3, vl);
            vfy_j = __riscv_vfsub_vv_f32m8(vfy_j, vfy4, vl);
            vfy_j = __riscv_vfsub_vv_f32m8(vfy_j, vfy1, vl);
            vfy_j = __riscv_vfmul_vf_f32m8(vfy_j, half, vl);

            // rarea = 1.0f / (xi * yj - xj * yi + ptiny)
            vfloat32m8_t varea = __riscv_vfmul_vv_f32m8(vxi, vyj, vl);
            varea = __riscv_vfmsub_vv_f32m8(varea, vxj, vyi, vl);
            varea = __riscv_vfadd_vv_f32m8(varea, vptiny, vl);
            vfloat32m8_t vone = __riscv_vfmv_v_f_f32m8(1.0f, vl);
            vfloat32m8_t vrarea = __riscv_vfdiv_vv_f32m8(vone, varea, vl);

            // dfxdx = rarea * (fxi * yj - fxj * yi)
            vfloat32m8_t vdfxdx = __riscv_vfmul_vv_f32m8(vfxi, vyj, vl);
            vdfxdx = __riscv_vfmsub_vv_f32m8(vdfxdx, vfxj, vyi, vl);
            vdfxdx = __riscv_vfmul_vv_f32m8(vdfxdx, vrarea, vl);

            // dfydy = rarea * (fyj * xi - fyi * xj)
            vfloat32m8_t vdfydy = __riscv_vfmul_vv_f32m8(vfy_j, vxi, vl);
            vdfydy = __riscv_vfmsub_vv_f32m8(vdfydy, vfy_i, vxj, vl);
            vdfydy = __riscv_vfmul_vv_f32m8(vdfydy, vrarea, vl);

            // affine = (fy1 + fy2 + fy3 + fy4) / (y1 + y2 + y3 + y4)
            vfloat32m8_t vaff_num = __riscv_vfadd_vv_f32m8(vfy1, vfy2, vl);
            vaff_num = __riscv_vfadd_vv_f32m8(vaff_num, vfy3, vl);
            vaff_num = __riscv_vfadd_vv_f32m8(vaff_num, vfy4, vl);

            vfloat32m8_t vaff_den = __riscv_vfadd_vv_f32m8(vy1, vy2, vl);
            vaff_den = __riscv_vfadd_vv_f32m8(vaff_den, vy3, vl);
            vaff_den = __riscv_vfadd_vv_f32m8(vaff_den, vy4, vl);
            vfloat32m8_t vaffine = __riscv_vfdiv_vv_f32m8(vaff_num, vaff_den, vl);

            vfloat32m8_t vres = __riscv_vfadd_vv_f32m8(vdfxdx, vdfydy, vl);
            vres = __riscv_vfadd_vv_f32m8(vres, vaffine, vl);

            __riscv_vse32_v_f32m8(&apps_div[i], vres, vl);
            i += vl;
        }
#endif
        for (; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
            real_t fyi = half * ( apps_fy1[i] + apps_fy2[i] - apps_fy3[i] - apps_fy4[i] );
            real_t fyj = half * ( apps_fy2[i] + apps_fy3[i] - apps_fy4[i] - apps_fy1[i] );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx  = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy  = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                            ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );
            apps_div[i] = dfxdx + dfydy + affine;
        }
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

