real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;

    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        int i = 0;
#if defined(__riscv_vector)
        for (; i <= APPS_N1D - 1; ) {
            size_t vl = __riscv_vsetvl_e32m8(APPS_N1D - i);

            vfloat32m8_t v_delvc = __riscv_vle32_v_f32m8(&apps_delvc[i], vl);
            vfloat32m8_t v_p_old = __riscv_vle32_v_f32m8(&apps_p_old[i], vl);
            vfloat32m8_t v_q_old = __riscv_vle32_v_f32m8(&apps_q_old[i], vl);
            vfloat32m8_t v_work = __riscv_vle32_v_f32m8(&apps_work[i], vl);
            vfloat32m8_t v_e_old = __riscv_vle32_v_f32m8(&apps_e_old[i], vl);

            vfloat32m8_t v_sum_pq = __riscv_vfadd_vv_f32m8(v_p_old, v_q_old, vl);
            vfloat32m8_t v_term1 = __riscv_vfmul_vv_f32m8(v_delvc, v_sum_pq, vl);
            vfloat32m8_t v_e_new = __riscv_vfmul_vf_f32m8(v_term1, 0.5f, vl);
            v_e_new = __riscv_vfsub_vv_f32m8(v_e_old, v_e_new, vl);
            vfloat32m8_t v_work_half = __riscv_vfmul_vf_f32m8(v_work, 0.5f, vl);
            v_e_new = __riscv_vfadd_vv_f32m8(v_e_new, v_work_half, vl);

            vfloat32m8_t v_q_new;
            vbool32_t mask_pos = __riscv_vmfgt_vf_f32m8_b4(v_delvc, 0.0f, vl);

            vfloat32m8_t v_compHalf = __riscv_vle32_v_f32m8(&apps_compHalfStep[i], vl);
            vfloat32m8_t v_vhalf = __riscv_vfadd_vf_f32m8(v_compHalf, 1.0f, vl);
            v_vhalf = __riscv_vfdiv_vf_f32m8(__riscv_vfmv_v_f_f32m8(1.0f, vl), v_vhalf, vl);

            vfloat32m8_t v_pbvc = __riscv_vle32_v_f32m8(&apps_pbvc[i], vl);
            vfloat32m8_t v_bvc = __riscv_vle32_v_f32m8(&apps_bvc[i], vl);
            vfloat32m8_t v_pHalf = __riscv_vle32_v_f32m8(&apps_pHalfStep[i], vl);

            vfloat32m8_t v_ssc = __riscv_vfmul_vv_f32m8(v_pbvc, v_e_new, vl);
            vfloat32m8_t v_vhalf2 = __riscv_vfmul_vv_f32m8(v_vhalf, v_vhalf, vl);
            vfloat32m8_t v_term_ssc = __riscv_vfmul_vv_f32m8(v_vhalf2, v_bvc, vl);
            v_term_ssc = __riscv_vfmul_vv_f32m8(v_term_ssc, v_pHalf, vl);
            v_ssc = __riscv_vfadd_vv_f32m8(v_ssc, v_term_ssc, vl);
            v_ssc = __riscv_vfdiv_vf_f32m8(v_ssc, rho0, vl);

            float temp_ssc[vl];
            __riscv_vse32_v_f32m8(temp_ssc, v_ssc, vl);
            for(size_t j=0; j<vl; ++j) {
                if (temp_ssc[j] <= 1.111111e-36f) temp_ssc[j] = 3.333333e-18f;
                else temp_ssc[j] = sqrtf(temp_ssc[j]);
            }
            v_ssc = __riscv_vle32_v_f32m8(temp_ssc, vl);

            vfloat32m8_t v_ql_old = __riscv_vle32_v_f32m8(&apps_ql_old[i], vl);
            vfloat32m8_t v_qq_old = __riscv_vle32_v_f32m8(&apps_qq_old[i], vl);
            v_q_new = __riscv_vfmul_vv_f32m8(v_ssc, v_ql_old, vl);
