            v_e_new = __riscv_vmerge_vfmv_f32m8(mask_cut_real, v_e_new, 0.0f, vl);

            vbool32_t mask_emin = __riscv_vmflt_vf_f32m8_b4(v_e_new, emin, vl);
            v_e_new = __riscv_vmerge_vfmv_f32m8(mask_emin, v_e_new, emin, vl);

