real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;
    int nl_limit = iterations / 4 + 1;

    for (int nl = 0; nl < nl_limit; nl++) {
#if defined(__riscv_vector)
        size_t vl;
        vfloat32m1_t v_one = __riscv_vfmv_v_f_f32m1(1.0f, 1);
        vfloat32m1_t v_pmin = __riscv_vfmv_v_f_f32m1(pmin, 1);
        vfloat32m1_t v_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);

        for (Index_type i = 0; i < APPS_N1D; ) {
            vl = __riscv_vsetvl_e32m1(APPS_N1D - i);

            // Loop 1: apps_bvc[i] = cls * (apps_compression[i] + 1.0f)
            vfloat32m1_t v_comp = __riscv_vle32_v_f32m1(&apps_compression[i], vl);
            vfloat32m1_t v_bvc = __riscv_vfadd_vv_f32m1(v_comp, v_one, vl);
            v_bvc = __riscv_vfmul_vf_f32m1(v_bvc, cls, vl);
            __riscv_vse32_v_f32m1(&apps_bvc[i], v_bvc, vl);

            // Loop 2: Pressure calculation
            vfloat32m1_t v_e_old = __riscv_vle32_v_f32m1(&apps_e_old[i], vl);
            vfloat32m1_t v_p = __riscv_vfmul_vv_f32m1(v_bvc, v_e_old, vl);

            // if (ABS(p) < p_cut) p = 0.0f;
            vfloat32m1_t v_abs_p = __riscv_vfabs_v_f32m1(v_p, vl);
            vbool32_t mask_cut = __riscv_vmflt_vf_f32m1(v_abs_p, p_cut, vl);
            v_p = __riscv_vmerge_vvm_f32m1(mask_cut, v_zero, v_p, vl);

            // if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            vfloat32m1_t v_vnewc = __riscv_vle32_v_f32m1(&apps_vnewc[i], vl);
            vbool32_t mask_eos = __riscv_vmfge_vf_f32m1(v_vnewc, eosvmax, vl);
            v_p = __riscv_vmerge_vvm_f32m1(mask_eos, v_zero, v_p, vl);

            // if (p < pmin) p = pmin;
            v_p = __riscv_vfmax_vv_f32m1(v_p, v_pmin, vl);

            __riscv_vse32_v_f32m1(&apps_p_new[i], v_p, vl);
            i += vl;
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
            if (ABS(p) < p_cut)         p = 0.0f;
            if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            if (p < pmin)               p = pmin;
            apps_p_new[i] = p;
        }
#endif
        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

