            // The operation is y[i] = 1.0f + alpha * x[i]
            // Use vfmacc.vf: vd = vd + (vs2 * rs1)
            // We must ensure the base value is exactly 1.0f
            vfloat32m1_t vy = __riscv_vfmv_v_f_f32m1(vl, one);
            vy = __riscv_vfmacc_vf_f32m1(vy, alpha, vx, vl);

            __riscv_vse32_v_f32m1(&y[i], vy, vl);
            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            y[i] = 1.0f + alpha * x[i];
        }
#endif
        dummy(y, x, NULL, NULL, NULL, alpha);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

