real_t basic_if_quad(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        int i = 0;
        size_t vl;
        for (; i < LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            vfloat32m1_t va = __riscv_vle32_v_f32m1(&a[i], vl);
            vfloat32m1_t vb = __riscv_vle32_v_f32m1(&b[i], vl);
            vfloat32m1_t vc = __riscv_vle32_v_f32m1(&c[i], vl);

            // s = b*b - 4.0*a*c
            vfloat32m1_t b2 = __riscv_vfmul_vv_f32m1(vb, vb, vl);
            vfloat32m1_t ac = __riscv_vfmul_vv_f32m1(va, vc, vl);
            vfloat32m1_t ac4 = __riscv_vfmul_vf_f32m1(ac, 4.0f, vl);
            vfloat32m1_t vs = __riscv_vfsub_vv_f32m1(b2, ac4, vl);

            // Mask for s >= 0
            vbool32_t mask = __riscv_vmfge_vf_f32m1_b32(vs, 0.0f, vl);

            // Calculate sqrt(s) where mask is true
            vfloat32m1_t vsqrt_s = __riscv_vfsqrt_v_f32m1_m(mask, vs, vl);

            // Denominator: 2.0 * a
            vfloat32m1_t vdenom = __riscv_vfmul_vf_f32m1(va, 2.0f, vl);

            // Corrected: Use vfdiv_vv for vector/vector division
            vfloat32m1_t vone = __riscv_vfmv_v_f_f32m1(vl, 1.0f);
            vfloat32m1_t vinv_denom = __riscv_vfdiv_vv_f32m1(vone, vdenom, vl);

            // out2 = (-b + s) / (2a)
            vfloat32m1_t vneg_b = __riscv_vfneg_v_f32m1(vb, vl);
            vfloat32m1_t vnum2 = __riscv_vfadd_vv_f32m1(vneg_b, vsqrt_s, vl);
            vfloat32m1_t vout2 = __riscv_vfmul_vv_f32m1(vnum2, vinv_denom, vl);

            // out1 = (-b - s) / (2a)
            vfloat32m1_t vnum1 = __riscv_vfsub_vv_f32m1(vneg_b, vsqrt_s, vl);
            vfloat32m1_t vout1 = __riscv_vfmul_vv_f32m1(vnum1, vinv_denom, vl);

            // If s < 0, out = 0.0
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(vl, 0.0f);
            vout1 = __riscv_vmerge_v_f32m1(mask, vout1, vzero, vl);
            vout2 = __riscv_vmerge_v_f32m1(mask, vout2, vzero, vl);

            __riscv_vse32_v_f32m1(&out1[i], vout1, vl);
            __riscv_vse32_v_f32m1(&out2[i], vout2, vl);
        }
#else
        for (int i = 0; i < LEN_1D; ++i) {
            real_t s = b[i]*b[i] - 4.0*a[i]*c[i];
            if (s >= 0) {
                s = sqrtf(s);
                out2[i] = (-b[i]+s)/(2.0*a[i]);
                out1[i] = (-b[i]-s)/(2.0*a[i]);
