real_t basic_indexlist(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type len = 0;
    int outer_limit = iterations / 8 + 1;

    for (int nl = 0; nl < outer_limit; nl++) {
        Index_type count = 0;
        Index_type i = 0;

#if defined(__riscv_vector)
        // Use e32 for float (real_t is float) and e64 for Index_type (uint64_t)
        for (; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            // Load x[i...i+vl-1] as floats
            vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[i], vl);

            // Compare x[i] < 0.0
            vbool32_t mask = __riscv_vmflt_vf_f32m1(vx, 0.0f, vl);

            // Count set bits in mask
            uint64_t active_count = __riscv_vpopc_vm_u32m1(mask, vl);

            // Generate sequence 0, 1, ..., vl-1 and add offset i
            // We need e64 for the indices to match Index_type
            vuint64m1_t vindices = __riscv_vsetiv_u64m1(0, vl);
            vuint64m1_t voffset = __riscv_vmv_v_x_u64m1(i, vl);
            vuint64m1_t vfinal_idx = __riscv_vadd_vv_u64m1(vindices, voffset, vl);

            // Compress indices into a temporary vector
            // vcompress requires the mask to match the element width of the source
            // Since mask is vbool32 and vfinal_idx is vuint64, we must be careful.
            // In RVV, vcompress uses the mask's bit-pattern.
            vuint64m1_t vcompressed = __riscv_vcompress_vm_u64m1(vfinal_idx, mask, vl);

            // Store the compressed elements
            __riscv_vse64_v_u64m1(&idx_list[count], vcompressed, active_count);

            count += active_count;
            i += vl;
        }
#else
        for (Index_type j = 0; j < LEN_1D; ++j) {
            if (x[j] < 0.0) {
                idx_list[count++] = j;
            }
        }
#endif
        len = count;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }
    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

