            vl = __riscv_vsetvl_e64m1(LEN_1D - i);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1((double *)&x[i], vl);

            // Use vmflt to get a mask. In RVV intrinsics, masks are vbool_t.
            vbool64_t mask = __riscv_vmflt_vf_f64m1(vx, 0.0, vl);

            // Convert mask to 1s and 0s. 
            // vmerge_v_vx: if mask is true, take value from vx (which we set to 1), else take scalar.
            vuint64m1_t val = __riscv_vmerge_v_vx_u64m1(mask, __riscv_vvmv_v_x_u64m1(0, vl), 1, vl);

            __riscv_vse64_v_u64m1((uint64_t *)&idx_counts[i], val, vl);
        }
#else
        for (Index_type i_scalar = 0; i_scalar < LEN_1D; ++i_scalar) {
            idx_counts[i_scalar] = (x[i_scalar] < 0.0) ? 1 : 0;
        }
#endif

        // Loop 2: Prefix Sum (Scan)
        Index_type count = 0;
        for (Index_type i_scan = 0; i_scan <= LEN_1D; ++i_scan) {
            Index_type inc = idx_counts[i_scan];
            idx_counts[i_scan] = count;
            count += inc;
        }

        // Loop 3: idx_list[idx_counts[i]] = i if idx_counts[i] != idx_counts[i+1]
        for (Index_type i_list = 0; i_list < LEN_1D; ++i_list) {
            if (idx_counts[i_list] != idx_counts[i_list+1]) {
                idx_list[idx_counts[i_list]] = i_list;
            }
        }

        len = idx_counts[LEN_1D];
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }
    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

