real_t basic_init3(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    #if defined(__riscv_vector)
    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
        if (sizeof(real_t) == sizeof(float)) {
            size_t vlmax = __riscv_vsetvlmax_e32m8();
            while (i < LEN_1D) {
                size_t vl = __riscv_vsetvl_e32m8(LEN_1D - i);
                vfloat32m8_t v_in1 = __riscv_vle32_v_f32m8((const float*)&in1[i], vl);
                vfloat32m8_t v_in2 = __riscv_vle32_v_f32m8((const float*)&in2[i], vl);
                vfloat32m8_t v_res = __riscv_vfneg_v_f32m8(v_in1, vl);
                v_res = __riscv_vfsub_vv_f32m8(v_res, v_in2, vl);
                __riscv_vse32_v_f32m8((float*)&out1[i], v_res, vl);
                __riscv_vse32_v_f32m8((float*)&out2[i], v_res, vl);
                __riscv_vse32_v_f32m8((float*)&out3[i], v_res, vl);
                i += vl;
            }
        } else if (sizeof(real_t) == sizeof(double)) {
            size_t vlmax = __riscv_vsetvlmax_e64m8();
            while (i < LEN_1D) {
                size_t vl = __riscv_vsetvl_e64m8(LEN_1D - i);
                vfloat64m8_t v_in1 = __riscv_vle64_v_f64m8((const double*)&in1[i], vl);
                vfloat64m8_t v_in2 = __riscv_vle64_v_f64m8((const double*)&in2[i], vl);
                vfloat64m8_t v_res = __riscv_vfneg_v_f64m8(v_in1, vl);
                v_res = __riscv_vfsub_vv_f64m8(v_res, v_in2, vl);
                __riscv_vse64_v_f64m8((double*)&out1[i], v_res, vl);
                __riscv_vse64_v_f64m8((double*)&out2[i], v_res, vl);
                __riscv_vse64_v_f64m8((double*)&out3[i], v_res, vl);
                i += vl;
            }
        } else {
            for (Index_type j = 0; j < LEN_1D; ++j) {
                out1[j] = out2[j] = out3[j] = -in1[j] - in2[j];
            }
        }
        dummy(out1, out2, out3, in1, in2, 0.0);
    }
    #else
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = 0; i < LEN_1D; ++i) {
            out1[i] = out2[i] = out3[i] = -in1[i] - in2[i];
        }
        dummy(out1, out2, out3, in1, in2, 0.0);
    }
    #endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

