real_t basic_init_view1d_offset(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t val = 1.0e-7;
    Index_type ibegin = 1;
    size_t n = LEN_1D - ibegin;

#if defined(__riscv_vector)
    for (int nl = 0; nl < iterations; nl++) {
        size_t j = 0;
        while (j < n) {
            size_t vl = __riscv_vsetvl_e64m1(n - j);

            // Generate sequence: j, j+1, ..., j+vl-1
            // Use __riscv_vid_v_i64m1 to get vector indices [0, 1, ..., vl-1]
            vint64m1_t v_id = __riscv_vid_v_i64m1(vl);

            // Add current offset j to the indices: [j, j+1, ..., j+vl-1]
            vint64m1_t v_idx = __riscv_vadd_vx_i64m1(v_id, j, vl);

            // Convert indices to float64: (real_t)(j + k)
            vfloat64m1_t v_f_idx = __riscv_vfcvt_f_x_f64m1(v_idx, vl);

            // Add ibegin to indices: (real_t)(j + k + ibegin)
            v_f_idx = __riscv_vfadd_vf_f64m1(v_f_idx, (real_t)ibegin, vl);

            // Multiply by val: (real_t)(j + k + ibegin) * val
            vfloat64m1_t v_res = __riscv_vfmul_vf_f64m1(v_f_idx, val, vl);

            // Store result to a[j]
            __riscv_vse64_v_f64m1(&a[j], v_res, vl);

            j += vl;
        }
        dummy(a, NULL, NULL, NULL, NULL, val);
    }
#else
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = ibegin; i < LEN_1D; ++i) {
            a[i - ibegin] = (real_t)i * val;
        }
        dummy(a, NULL, NULL, NULL, NULL, val);
    }
#endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

