real_t basic_muladdsub(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
#if defined(__riscv_vector)
        size_t vl;
        for (; i < LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);
            vfloat32m1_t v_in1 = __riscv_vle32_v_f32m1(&in1[i], vl);
            vfloat32m1_t v_in2 = __riscv_vle32_v_f32m1(&in2[i], vl);

            vfloat32m1_t v_mul = __riscv_vfmul_vv_f32m1(v_in1, v_in2, vl);
            vfloat32m1_t v_add = __riscv_vfadd_vv_f32m1(v_in1, v_in2, vl);
            vfloat32m1_t v_sub = __riscv_vfsub_vv_f32m1(v_in1, v_in2, vl);

            __riscv_vse32_v_f32m1(&out1[i], v_mul, vl);
            __riscv_vse32_v_f32m1(&out2[i], v_add, vl);
            __riscv_vse32_v_f32m1(&out3[i], v_sub, vl);
        }
#else
        for (; i < LEN_1D; ++i) {
            out1[i] = in1[i] * in2[i];
            out2[i] = in1[i] + in2[i];
            out3[i] = in1[i] - in2[i];
        }
#endif
        dummy(out1, out2, out3, in1, in2, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

