real_t basic_nested_init(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type nk = 8, nj = LEN_2D, ni = LEN_2D;
    const real_t scale = 0.00000001;

    for (int nl = 0; nl < iterations / 32 + 1; nl++) {
        for (Index_type k = 0; k < nk; ++k) {
            real_t k_val = (real_t)k;
            for (Index_type j = 0; j < nj; ++j) {
                real_t jk_val = (real_t)j * k_val * scale;
                real_t *ptr = &array3d[ni * (j + nj * k)];

                Index_type i = 0;
#if defined(__riscv_vector)
                while (i < ni) {
                    size_t vl = __riscv_vsetvl_e64m1(ni - i);

                    // Use __riscv_vid_v_u64m1 as it is the standard intrinsic for vector indices
                    vuint64m1_t v_idx_u = __riscv_vid_v_u64m1(vl);
                    // Cast to signed for addition and conversion
                    vint64m1_t v_idx = __riscv_vreinterpret_v_i64m1(v_idx_u);

                    // Use __riscv_vmv_v_x_i64m1 to broadcast the scalar offset i
                    vint64m1_t v_i_offset = __riscv_vmv_v_x_i64m1(vl, i);
                    vint64m1_t v_i_final = __riscv_vadd_i64m1(v_idx, v_i_offset, vl);

                    // Convert integer indices to float64
                    vfloat64m1_t v_i_float = __riscv_vfcvt_f_x_f64m1(v_i_final, vl);
                    // Multiply by the precomputed scalar (j * k * scale)
                    vfloat64m1_t v_res = __riscv_vfmul_vf_f64m1(v_i_float, jk_val, vl);

                    // Store result to memory
                    __riscv_vse64_v_f64m1(ptr + i, v_res, vl);
                    i += vl;
                }
#else
                for (Index_type i_inner = 0; i_inner < ni; ++i_inner) {
                    ptr[i_inner] = jk_val * (real_t)i_inner;
                }
#endif
            }
        }
        dummy(array3d, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

