#include <riscv_vector.h>
#endif

real_t basic_pi_atomic(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dx = 1.0 / (real_t)LEN_1D;
    real_t pi_acc = 0.0;

    for (int nl = 0; nl < iterations; nl++) {
        real_t pi = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        int i = 0;
        // Use __riscv_vsetvlmax() is not a function, it's a macro or we use __riscv_vsetvl_e64m1
        vfloat64m1_t v_pi_sum = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvl_e64m1(0));

        while (i < LEN_1D) {
            vl = __riscv_vsetvl_e64m1(LEN_1D - i);

            // Generate sequence [i, i+1, ..., i+vl-1]
            // Since __riscv_vsetiv_i64m1 is not available in this toolchain, 
            // we use __riscv_vid_v_i64m1 and add the base index i.
            vint64m1_t v_idx = __riscv_vid_v_i64m1(vl);
            v_idx = __riscv_vadd_vx_i64m1(v_idx, i, vl);

            vfloat64m1_t v_xv = __riscv_vfcvt_f_x_f64m1(v_idx, vl);
            v_xv = __riscv_vfadd_vf_f64m1(v_xv, 0.5, vl);
            v_xv = __riscv_vfmul_vf_f64m1(v_xv, dx, vl);

            vfloat64m1_t v_denom = __riscv_vfmul_vv_f64m1(v_xv, v_xv, vl);
            v_denom = __riscv_vfadd_vf_f64m1(v_denom, 1.0, vl);

            vfloat64m1_t v_term = __riscv_vfdiv_vf_f64m1(dx, v_denom, vl);

            v_pi_sum = __riscv_vfadd_vv_f64m1(v_pi_sum, v_term, vl);
            i += vl;
        }

        vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_pi_sum, v_zero, __riscv_vsetvl_e64m1(0));
        pi = __riscv_vfmv_f_s_f64m1_f64(v_res);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = ((real_t)i + 0.5) * dx;
            pi += dx / (1.0 + xv * xv);
        }
        #endif

        pi_acc += pi * 4.0;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }
    x[0] = pi_acc / (real_t)iterations;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t basic_pi_reduce(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dx = 1.0 / (real_t)LEN_1D;
    real_t pi_acc = 0.0;

    for (int nl = 0; nl < iterations; nl++) {
        real_t pi = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        vfloat64m1_t v_pi = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());

        int i = 0;
        for (; i < LEN_1D; ) {
            vl = __riscv_vsetvl_e64m1(LEN_1D - i);

            // xv = (i + 0.5) * dx
            // Use __riscv_vid_v_u64m1 and convert to float64
            vuint64m1_t v_idx_u = __riscv_vid_v_u64m1(vl);
            vfloat64m1_t v_idx_f = __riscv_vfcvt_f_u_f64m1(v_idx_u, vl);

            // Offset by current loop index i
            vfloat64m1_t v_xv = __riscv_vfadd_vf_f64m1(v_idx_f, (real_t)i, vl);
            // Add 0.5
            v_xv = __riscv_vfadd_vf_f64m1(v_xv, 0.5, vl);
            // Multiply by dx
            v_xv = __riscv_vfmul_vf_f64m1(v_xv, dx, vl);

            // term = dx / (1.0 + xv * xv)
            vfloat64m1_t v_denom = __riscv_vfmul_vv_f64m1(v_xv, v_xv, vl);
            v_denom = __riscv_vfadd_vf_f64m1(v_denom, 1.0, vl);

            // Correct intrinsic for scalar / vector: __riscv_vfdiv_vf_f64m1(vector, scalar, vl)
            // To get dx / v_denom, we can use 1.0 / v_denom then multiply by dx, 
            // or use vfdiv_vf with 1.0 and then multiply.
            // Actually, the standard intrinsic is __riscv_vfdiv_vf_f64m1(v_denom, dx, vl) 
            // which computes v_denom / dx. We need dx / v_denom.
            // We use vfdiv_vf(v_denom, 1.0, vl) to get 1/v_denom, then multiply by dx.
            vfloat64m1_t v_inv_denom = __riscv_vfdiv_vf_f64m1(v_denom, 1.0, vl);
            vfloat64m1_t v_term = __riscv_vfmul_vf_f64m1(v_inv_denom, dx, vl);

            v_pi = __riscv_vfadd_vv_f64m1(v_pi, v_term, vl);
            i += vl;
        }
        // Reduction
        vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_zero, v_pi, 0);
        pi = __riscv_vfmv_f_s_f64m1_f64(v_res);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = ((real_t)i + 0.5) * dx;
            pi += dx / (1.0 + xv * xv);
        }
        #endif

        pi_acc += pi * 4.0;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }
    x[0] = pi_acc / (real_t)iterations;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

