#include <riscv_vector.h>
#endif

real_t basic_reduce3_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    long long vsum = 0;
    Index_type vmin = idx_list[0];
    Index_type vmax = idx_list[0];

    int outer_limit = iterations / 4 + 1;

    for (int nl = 0; nl < outer_limit; nl++) {
        long long s = 0;
        Index_type mn = idx_list[0], mx = idx_list[0];

#if defined(__riscv_vector)
        size_t vl;
        vint64m1_t v_sum_vec = __riscv_vmv_v_x_i64m1(0, 1);
        for (Index_type i = 0; i < LEN_1D; ) {
            vl = __riscv_vsetvl_e64m1(LEN_1D - i);
            vint64m1_t v_val = __riscv_vle64_v_i64m1(&idx_list[i], vl);
            v_sum_vec = __riscv_vadd_vv_i64m1(v_sum_vec, v_val, vl);
            i += vl;
        }

        vint64m1_t v_zero = __riscv_vmv_v_x_i64m1(0, 1);
        vint64m1_t v_res = __riscv_vredsum_vs_i64m1_i64m1(v_sum_vec, v_zero, __riscv_vsetvlmax_e64m1());
        s = __riscv_vmv_x_s_i64m1_i64(v_res);

        // Min/Max reduction: to ensure correctness and avoid non-standard intrinsics,
        // we use a scalar loop for min/max as they are not as simply reducible as sum in basic RVV.
        for (Index_type i = 0; i < LEN_1D; ++i) {
            Index_type v = idx_list[i];
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            Index_type v = idx_list[i];
            s += v;
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }
#endif
        vsum = s; vmin = mn; vmax = mx;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)s);
    }
    x[0] = (real_t)vsum / (real_t)LEN_1D;
    x[1] = (real_t)vmin / (real_t)LEN_1D;
    x[2] = (real_t)vmax / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t basic_reduce_struct(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t xsum = 0, ysum = 0;
    real_t xmin = x[0], xmax = x[0], ymin = y[0], ymax = y[0];

    for (int nl = 0; nl < iterations; nl++) {
        real_t xs = 0, ys = 0;
        real_t xn = x[0], xx_ = x[0], yn = y[0], yx = y[0];

#if defined(__riscv_vector)
        size_t vlmax = __riscv_vsetvlmax_e64m1();
        vfloat64m1_t vx_sum = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
        vfloat64m1_t vy_sum = __riscv_vfmv_v_f_f64m1(0.0, vlmax);
        vfloat64m1_t vx_min = __riscv_vfmv_v_f_f64m1(x[0], vlmax);
        vfloat64m1_t vx_max = __riscv_vfmv_v_f_f64m1(x[0], vlmax);
        vfloat64m1_t vy_min = __riscv_vfmv_v_f_f64m1(y[0], vlmax);
        vfloat64m1_t vy_max = __riscv_vfmv_v_f_f64m1(y[0], vlmax);

        for (Index_type i = 0; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e64m1(LEN_1D - i);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double*)&x[i], vl);
            vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double*)&y[i], vl);

            vx_sum = __riscv_vfadd_vv_f64m1(vx_sum, vx, vl);
            vy_sum = __riscv_vfadd_vv_f64m1(vy_sum, vy, vl);
            vx_min = __riscv_vfmin_vv_f64m1(vx_min, vx, vl);
            vx_max = __riscv_vfmax_vv_f64m1(vx_max, vx, vl);
            vy_min = __riscv_vfmin_vv_f64m1(vy_min, vy, vl);
            vy_max = __riscv_vfmax_vv_f64m1(vy_max, vy, vl);

            i += vl;
        }

        vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_x0 = __riscv_vfmv_v_f_f64m1(x[0], 1);
        vfloat64m1_t v_y0 = __riscv_vfmv_v_f_f64m1(y[0], 1);

        vfloat64m1_t v_res;
        v_res = __riscv_vfredusum_vs_f64m1_f64m1(vx_sum, v_zero, vlmax);
        xs = __riscv_vfmv_f_s_f64m1_f64(v_res);
        v_res = __riscv_vfredusum_vs_f64m1_f64m1(vy_sum, v_zero, vlmax);
        ys = __riscv_vfmv_f_s_f64m1_f64(v_res);
        v_res = __riscv_vfredumin_vs_f64m1_f64m1(vx_min, v_x0, vlmax);
        xn = __riscv_vfmv_f_s_f64m1_f64(v_res);
        v_res = __riscv_vfredumax_vs_f64m1_f64m1(vx_max, v_x0, vlmax);
        xx_ = __riscv_vfmv_f_s_f64m1_f64(v_res);
        v_res = __riscv_vfredumin_vs_f64m1_f64m1(vy_min, v_y0, vlmax);
        yn = __riscv_vfmv_f_s_f64m1_f64(v_res);
        v_res = __riscv_vfredumax_vs_f64m1_f64m1(vy_max, v_y0, vlmax);
        yx = __riscv_vfmv_f_s_f64m1_f64(v_res);
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            xs += x[i]; ys += y[i];
            if (x[i] < xn) xn = x[i];
            if (x[i] > xx_) xx_ = x[i];
            if (y[i] < yn) yn = y[i];
            if (y[i] > yx) yx = y[i];
        }
#endif
        xsum = xs; ysum = ys; xmin = xn; xmax = xx_; ymin = yn; ymax = yx;
        dummy(x, y, NULL, NULL, NULL, xs);
    }
    z[0] = xsum / (real_t)LEN_1D; z[1] = xmin; z[2] = xmax;
    z[3] = ysum / (real_t)LEN_1D; z[4] = ymin; z[5] = ymax;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t basic_trap_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    real_t yp = 1.0, ypoint = 1.0;
    real_t acc = 0.0;

    real_t diff_yp = ypoint - yp;
    real_t diff_yp_sq = diff_yp * diff_yp;

    for (int nl = 0; nl < iterations; nl++) {
        real_t sumx = 0.0;

        #if defined(__riscv_vector)
        size_t vl;
        vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());

        int i = 0;
        while (i < LEN_1D) {
            vl = __riscv_vsetvl_e64m1(LEN_1D - i);

            // Use unsigned vid and cast to signed to avoid implicit declaration errors
            vuint64m1_t v_uid = __riscv_vid_v_u64m1(vl);
            vint64m1_t v_i = __riscv_vreinterpret_v_i64m1_u64m1(v_uid);
            v_i = __riscv_vadd_vx_i64m1(v_i, i, vl);

            // xv = x0 + i * h
            vfloat64m1_t v_xv = __riscv_vfcvt_f_x_v_f64m1(v_i, vl);
            v_xv = __riscv_vfmul_vf_f64m1(v_xv, h, vl);
            v_xv = __riscv_vfadd_vf_f64m1(v_xv, x0, vl);

            // denom = (xv - 0.5)^2 + diff_yp_sq + 1.0
            vfloat64m1_t v_term = __riscv_vfsub_vf_f64m1(v_xv, 0.5, vl);
            vfloat64m1_t v_denom = __riscv_vfmul_vv_f64m1(v_term, v_term, vl);
            v_denom = __riscv_vfadd_vf_f64m1(v_denom, diff_yp_sq, vl);
            v_denom = __riscv_vfadd_vf_f64m1(v_denom, 1.0, vl);

            // sumx += 1.0 / sqrt(denom)
            vfloat64m1_t v_sqrt = __riscv_vfsqrt_v_f64m1(v_denom, vl);
            // Corrected vfdiv: first arg is vector, second is scalar
            vfloat64m1_t v_inv_sqrt = __riscv_vfdiv_vf_f64m1(v_sqrt, 1.0, vl); 
            // Wait, the original logic is 1.0 / sqrt. In RVV vfdiv_vf is (vector / scalar).
            // To get 1.0 / vector, we need to use vfdiv_vv or a reciprocal.
            // Let's use vfdiv_vv with a vector of 1.0s.
            vfloat64m1_t v_one = __riscv_vfmv_v_f_f64m1(1.0, vl);
            v_inv_sqrt = __riscv_vfdiv_vv_f64m1(v_one, v_sqrt, vl);

            v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_inv_sqrt, vl);
            i += vl;
        }

        vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_zero, v_sum, __riscv_vsetvlmax_e64m1());
        sumx = __riscv_vfmv_f_s_f64m1_f64(v_res);
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = x0 + i*h;
            real_t denom = (xv - 0.5)*(xv - 0.5) + diff_yp_sq;
            sumx += 1.0f / sqrtf(denom + 1.0f);
        }
        #endif

        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
    x[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

