real_t lcals_diff_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;

    for (int nl = 0; nl < iterations; nl++) {
        #if defined(__riscv_vector)
        int i = 0;
        // Use a larger LMUL to reduce loop overhead and improve throughput
        size_t vlmax = __riscv_vsetvl_e32m8(LEN_1D);

        for (; i < LEN_1D; i += vlmax) {
            size_t vl = __riscv_vsetvl_e32m8(LEN_1D - i);

            // Pre-calculate base pointers to avoid repeated multiplication in the loop
            real_t *p_cx = &cx[i + offset * 4];
            real_t *p_px4 = &px[i + offset * 4];
            real_t *p_px5 = &px[i + offset * 5];
            real_t *p_px6 = &px[i + offset * 6];
            real_t *p_px7 = &px[i + offset * 7];
            real_t *p_px8 = &px[i + offset * 8];
            real_t *p_px9 = &px[i + offset * 9];
            real_t *p_px10 = &px[i + offset * 10];
            real_t *p_px11 = &px[i + offset * 11];
            real_t *p_px12 = &px[i + offset * 12];
            real_t *p_px13 = &px[i + offset * 13];

            vfloat32m8_t v_ar = __riscv_vle32_v_f32m8(p_cx, vl);
            vfloat32m8_t v_px = __riscv_vle32_v_f32m8(p_px4, vl);

            vfloat32m8_t v_br = __riscv_vfsub_vv_f32m8(v_ar, v_px, vl);
            __riscv_vse32_v_f32m8(p_px4, v_ar, vl);

            v_px = __riscv_vle32_v_f32m8(p_px5, vl);
            vfloat32m8_t v_cr = __riscv_vfsub_vv_f32m8(v_br, v_px, vl);
            __riscv_vse32_v_f32m8(p_px5, v_br, vl);

            v_px = __riscv_vle32_v_f32m8(p_px6, vl);
            v_ar = __riscv_vfsub_vv_f32m8(v_cr, v_px, vl);
            __riscv_vse32_v_f32m8(p_px6, v_cr, vl);

            v_px = __riscv_vle32_v_f32m8(p_px7, vl);
            v_br = __riscv_vfsub_vv_f32m8(v_ar, v_px, vl);
            __riscv_vse32_v_f32m8(p_px7, v_ar, vl);

            v_px = __riscv_vle32_v_f32m8(p_px8, vl);
            v_cr = __riscv_vfsub_vv_f32m8(v_br, v_px, vl);
            __riscv_vse32_v_f32m8(p_px8, v_br, vl);

            v_px = __riscv_vle32_v_f32m8(p_px9, vl);
            v_ar = __riscv_vfsub_vv_f32m8(v_cr, v_px, vl);
            __riscv_vse32_v_f32m8(p_px9, v_cr, vl);

            v_px = __riscv_vle32_v_f32m8(p_px10, vl);
            v_br = __riscv_vfsub_vv_f32m8(v_ar, v_px, vl);
            __riscv_vse32_v_f32m8(p_px10, v_ar, vl);

            v_px = __riscv_vle32_v_f32m8(p_px11, vl);
            v_cr = __riscv_vfsub_vv_f32m8(v_br, v_px, vl);
            __riscv_vse32_v_f32m8(p_px11, v_br, vl);

            v_px = __riscv_vle32_v_f32m8(p_px12, vl);
            vfloat32m8_t v_res13 = __riscv_vfsub_vv_f32m8(v_cr, v_px, vl);
            __riscv_vse32_v_f32m8(p_px13, v_res13, vl);
            __riscv_vse32_v_f32m8(p_px12, v_cr, vl);
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t ar = cx[i + offset * 4];
            real_t br = ar - px[i + offset * 4];
            px[i + offset * 4]  = ar;
            real_t cr = br - px[i + offset * 5];
            px[i + offset * 5]  = br;
            ar = cr - px[i + offset * 6];  px[i + offset * 6]  = cr;
            br = ar - px[i + offset * 7];  px[i + offset * 7]  = ar;
            cr = br - px[i + offset * 8];  px[i + offset * 8]  = br;
            ar = cr - px[i + offset * 9];  px[i + offset * 9]  = cr;
            br = ar - px[i + offset * 10]; px[i + offset * 10] = ar;
            cr = br - px[i + offset * 11]; px[i + offset * 11] = br;
            px[i + offset * 13] = cr - px[i + offset * 12];
            px[i + offset * 12] = cr;
        }
        #endif
        dummy(cx, px, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_eos(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t r = 0.5, t = 0.25, q = 0.125;

    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
#if defined(__riscv_vector)
        size_t vlmax = __riscv_vsetvl_e32m1(LEN_1D - 6);
        for (; i <= (int)(LEN_1D - 6) - (int)vlmax; i += vlmax) {
            // Use scalar-vector intrinsics for constants
            // r * (z[i] + r * y[i])
            vfloat32m1_t vy_i = __riscv_vle32_v_f32m1(&y[i], vlmax);
            vfloat32m1_t vz_i = __riscv_vle32_v_f32m1(&z[i], vlmax);
            vfloat32m1_t v_ry_z = __riscv_vfmacc_vf_f32m1(vz_i, r, vy_i, vlmax);
            vfloat32m1_t v_r_ry_z = __riscv_vfmul_vf_f32m1(v_ry_z, r, vlmax);

            vfloat32m1_t vu_i1 = __riscv_vle32_v_f32m1(&u[i+1], vlmax);
            vfloat32m1_t vu_i2 = __riscv_vle32_v_f32m1(&u[i+2], vlmax);
            vfloat32m1_t vu_i3 = __riscv_vle32_v_f32m1(&u[i+3], vlmax);

            // t * (u[i+3] + r * (u[i+2] + r * u[i+1]))
            vfloat32m1_t v_ru_i1_u_i2 = __riscv_vfmacc_vf_f32m1(vu_i2, r, vu_i1, vlmax);
            vfloat32m1_t v_r_ru_i1_u_i2 = __riscv_vfmul_vf_f32m1(v_ru_i1_u_i2, r, vlmax);
            vfloat32m1_t v_u3_r_term = __riscv_vfadd_vv_f32m1(vu_i3, v_r_ru_i1_u_i2, vlmax);
            vfloat32m1_t v_t_u3_r_term = __riscv_vfmul_vf_f32m1(v_u3_r_term, t, vlmax);

            vfloat32m1_t vu_i4 = __riscv_vle32_v_f32m1(&u[i+4], vlmax);
            vfloat32m1_t vu_i5 = __riscv_vle32_v_f32m1(&u[i+5], vlmax);
            vfloat32m1_t vu_i6 = __riscv_vle32_v_f32m1(&u[i+6], vlmax);

            // t * (u[i+6] + q * (u[i+5] + q * u[i+4]))
            vfloat32m1_t v_qu_i4_u_i5 = __riscv_vfmacc_vf_f32m1(vu_i5, q, vu_i4, vlmax);
            vfloat32m1_t v_q_qu_i4_u_i5 = __riscv_vfmul_vf_f32m1(v_qu_i4_u_i5, q, vlmax);
            vfloat32m1_t v_u6_q_term = __riscv_vfadd_vv_f32m1(vu_i6, v_q_qu_i4_u_i5, vlmax);
            vfloat32m1_t v_t_u6_q_term = __riscv_vfmul_vf_f32m1(v_u6_q_term, t, vlmax);

            // x[i] = u[i] + v_r_ry_z + v_t_u3_r_term + v_t_u6_q_term
            vfloat32m1_t vu_i = __riscv_vle32_v_f32m1(&u[i], vlmax);
            vfloat32m1_t v_res = __riscv_vfadd_vv_f32m1(vu_i, v_r_ry_z, vlmax);
            v_res = __riscv_vfadd_vv_f32m1(v_res, v_t_u3_r_term, vlmax);
            v_res = __riscv_vfadd_vv_f32m1(v_res, v_t_u6_q_term, vlmax);

            __riscv_vse32_v_f32m1(&x[i], v_res, vlmax);
        }
#endif
        for (; i < LEN_1D - 6; ++i) {
            x[i] = u[i] + r*( z[i] + r*y[i] ) +
                          t*( u[i+3] + r*( u[i+2] + r*u[i+1] ) +
                             t*( u[i+6] + q*( u[i+5] + q*u[i+4] ) ) );
        }
        dummy(x, u, y, z, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

