real_t lcals_first_diff(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

#if defined(__riscv_vector)
    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
        int n = LEN_1D - 1;
        size_t vl;
        while (i < n) {
            vl = __riscv_vsetvl_e32m1(n - i);
            vfloat32m1_t vy_next = __riscv_vle32_v_f32m1((const float *)&y[i + 1], vl);
            vfloat32m1_t vy_curr = __riscv_vle32_v_f32m1((const float *)&y[i], vl);
            vfloat32m1_t vx = __riscv_vfsub_vv_f32m1(vy_next, vy_curr, vl);
            __riscv_vse32_v_f32m1((float *)&x[i], vx, vl);
            i += vl;
        }
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }
#else
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = 0; i < LEN_1D - 1; ++i) {
            x[i] = y[i+1] - y[i];
        }
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }
#endif

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

