#include <riscv_vector.h>
#endif

real_t lcals_first_min(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type loc = 0;
    real_t mn = x[0];

    for (int nl = 0; nl < iterations; nl++) {
        loc = 0;
        mn = x[0];

        #if defined(__riscv_vector)
        int i = 0;
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e64m1(LEN_1D - i);
            vfloat64m1_t v_x = __riscv_vle64_v_f64m1((const double*)&x[i], vl);

            // Use the correct intrinsic for float-scalar comparison
            vbool64_t mask = __riscv_vmflt_vf_f64m1(v_x, mn, vl);

            if (__riscv_vfirst_m_ul(mask, vl) != -1) {
                // To maintain the "first minimum" logic (updating mn and loc 
                // whenever a strictly smaller value is encountered), 
                // we process the elements of the vector sequentially 
                // if a potential new minimum is found.
                for (size_t j = 0; j < vl; ++j) {
                    if (x[i + j] < mn) {
                        mn = x[i + j];
                        loc = i + j;
                    }
                }
            }
            i += vl;
        }
        #else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < mn) { mn = x[i]; loc = i; }
        }
        #endif

        dummy(x, NULL, NULL, NULL, NULL, mn);
    }
    y[0] = mn;
    y[1] = (real_t)loc / (real_t)LEN_1D;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_first_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        int i = 1;
        if (__riscv_vector) {
            size_t vl;
            // We need to compute x[i] = y[i-1] + y[i]
            // This is a vector addition of y shifted by 1 and y
            for (; i <= (int)LEN_1D - 1; ) {
                vl = __riscv_vsetvl_e32m1(LEN_1D - i);

                // Load y[i]...y[i+vl-1]
                vfloat32m1_t v_y_curr = __riscv_vle32_v_f32m1(&y[i], vl);
                // Load y[i-1]...y[i+vl-2]
                vfloat32m1_t v_y_prev = __riscv_vle32_v_f32m1(&y[i-1], vl);

                vfloat32m1_t v_res = __riscv_vfadd_vv_f32m1(v_y_curr, v_y_prev, vl);

                __riscv_vse32_v_f32m1(&x[i], v_res, vl);

                i += vl;
            }
        } else {
            for (; i < LEN_1D; ++i) {
                x[i] = y[i-1] + y[i];
            }
        }
        dummy(x, y, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_gen_lin_recur(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type kb5i = 0;
    int nl_limit = iterations / 16 + 1;

    for (int nl = 0; nl < nl_limit; nl++) {
        // Forward loop: k = 0 to LEN_1D - 1
        Index_type k = 0;
        #if defined(__riscv_vector)
        size_t vl;
        for (; k < LEN_1D; k += vl) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - k);
            vfloat32m1_t v_sa = __riscv_vle32_v_f32m1(&sa[k], vl);
            vfloat32m1_t v_stb5 = __riscv_vle32_v_f32m1(&stb5[k], vl);
            vfloat32m1_t v_sb = __riscv_vle32_v_f32m1(&sb[k], vl);

            // b5[k+kb5i] = sa[k] + stb5[k]*sb[k]
            // Use vfmul + vfadd as vfmaccm is for accumulation into a destination
            vfloat32m1_t v_prod = __riscv_vfmul_vv_f32m1(v_stb5, v_sb, vl);
            vfloat32m1_t v_b5 = __riscv_vfadd_vv_f32m1(v_sa, v_prod, vl);
            __riscv_vse32_v_f32m1(&b5[k + kb5i], v_b5, vl);

            // stb5[k] = b5[k+kb5i] - stb5[k]
            vfloat32m1_t v_stb5_new = __riscv_vfsub_vv_f32m1(v_b5, v_stb5, vl);
            __riscv_vse32_v_f32m1(&stb5[k], v_stb5_new, vl);
        }
        #else
        for (; k < LEN_1D; ++k) {
            b5[k+kb5i] = sa[k] + stb5[k]*sb[k];
            stb5[k] = b5[k+kb5i] - stb5[k];
        }
        #endif

        // Backward loop: i = 1 to LEN_1D, k = LEN_1D - i
        // This is effectively k = LEN_1D - 1 down to 0
        Index_type kb = LEN_1D - 1;
        #if defined(__riscv_vector)
        while (kb >= 0) {
            size_t vl = __riscv_vsetvl_e32m1(kb + 1);
            Index_type start_k = kb - vl + 1;

            vfloat32m1_t v_sa = __riscv_vle32_v_f32m1(&sa[start_k], vl);
            vfloat32m1_t v_stb5 = __riscv_vle32_v_f32m1(&stb5[start_k], vl);
            vfloat32m1_t v_sb = __riscv_vle32_v_f32m1(&sb[start_k], vl);

            vfloat32m1_t v_prod = __riscv_vfmul_vv_f32m1(v_stb5, v_sb, vl);
            vfloat32m1_t v_b5 = __riscv_vfadd_vv_f32m1(v_sa, v_prod, vl);
            __riscv_vse32_v_f32m1(&b5[start_k + kb5i], v_b5, vl);

            vfloat32m1_t v_stb5_new = __riscv_vfsub_vv_f32m1(v_b5, v_stb5, vl);
            __riscv_vse32_v_f32m1(&stb5[start_k], v_stb5_new, vl);

            if (kb < vl) break;
            kb -= vl;
        }
        #else
        for (Index_type i = 1; i < LEN_1D + 1; ++i) {
            Index_type k_val = LEN_1D - i;
            b5[k_val+kb5i] = sa[k_val] + stb5[k_val]*sb[k_val];
            stb5[k_val] = b5[k_val+kb5i] - stb5[k_val];
        }
        #endif
        dummy(b5, stb5, sa, sb, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_hydro_1d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t q = 0.5, r = 0.25, t = 0.125;
    int n_elements = LEN_1D - 12;

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        int i = 0;
        // Use float (32-bit) vector types since real_t is float
        size_t vlmax = __riscv_vsetvl_e32m1(n_elements);

        for (; i < n_elements; i += vlmax) {
            size_t vl = __riscv_vsetvl_e32m1(n_elements - i);

            vfloat32m1_t v_y = __riscv_vle32_v_f32m1(&y[i], vl);
            vfloat32m1_t v_z10 = __riscv_vle32_v_f32m1(&z[i + 10], vl);
            vfloat32m1_t v_z11 = __riscv_vle32_v_f32m1(&z[i + 11], vl);

            // x[i] = q + y[i] * (r * z[i+10] + t * z[i+11])
            vfloat32m1_t v_inner = __riscv_vfmul_vf_f32m1(v_z10, r, vl);
            v_inner = __riscv_vfmacc_vf_f32m1(v_inner, t, v_z11, vl);
            vfloat32m1_t v_final = __riscv_vfmul_vv_f32m1(v_y, v_inner, vl);
            v_final = __riscv_vfadd_vf_f32m1(v_final, q, vl);

            __riscv_vse32_v_f32m1(&x[i], v_final, vl);
        }
#else
        for (Index_type i = 0; i < LEN_1D - 12; ++i) {
            x[i] = q + y[i]*( r*z[i+10] + t*z[i+11] );
        }
#endif
        dummy(x, y, z, NULL, NULL, q);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_hydro_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t s = 0.0001, t = 0.5;
    Index_type kn = LEN_2D, jn = LEN_2D;

    for (int nl = 0; nl < iterations / 32 + 1; nl++) {
        // Loop 1: Compute za and zb
        for (Index_type k = 1; k < kn - 1; ++k) {
            Index_type j = 1;
#if defined(__riscv_vector)
            size_t vlmax = __riscv_vsetvl_e32m1(jn - 2);
            for (; j <= jn - 2; j += vlmax) {
                size_t vl = __riscv_vsetvl_e32m1(jn - 1 - j);

                vfloat32m1_t vp_k1_j_m1 = __riscv_vlse32_v_f32m1(&zp[k+1][j-1], 1, vl);
                vfloat32m1_t vq_k1_j_m1 = __riscv_vlse32_v_f32m1(&zq[k+1][j-1], 1, vl);
                vfloat32m1_t vp_k_j_m1  = __riscv_vlse32_v_f32m1(&zp[k][j-1], 1, vl);
                vfloat32m1_t vq_k_j_m1  = __riscv_vlse32_v_f32m1(&zq[k][j-1], 1, vl);
                vfloat32m1_t vr_k_j     = __riscv_vle32_v_f32m1(&zr[k][j], vl);
                vfloat32m1_t vr_k_j_m1  = __riscv_vlse32_v_f32m1(&zr[k][j-1], 1, vl);
                vfloat32m1_t vm_k_j_m1  = __riscv_vlse32_v_f32m1(&zm[k][j-1], 1, vl);
                vfloat32m1_t vm_k1_j_m1 = __riscv_vlse32_v_f32m1(&zm[k+1][j-1], 1, vl);

                vfloat32m1_t term1_za = __riscv_vfadd_vv_f32m1(vp_k1_j_m1, vq_k1_j_m1, vl);
                vfloat32m1_t term2_za = __riscv_vfadd_vv_f32m1(vp_k_j_m1, vq_k_j_m1, vl);
                vfloat32m1_t diff_za = __riscv_vfsub_vv_f32m1(term1_za, term2_za, vl);
                vfloat32m1_t sum_zr_za = __riscv_vfadd_vv_f32m1(vr_k_j, vr_k_j_m1, vl);
                vfloat32m1_t sum_zm_za = __riscv_vfadd_vv_f32m1(vm_k_j_m1, vm_k1_j_m1, vl);
                vfloat32m1_t res_za = __riscv_vfdiv_vv_f32m1(__riscv_vfmul_vv_f32m1(diff_za, sum_zr_za, vl), sum_zm_za, vl);
                __riscv_vse32_v_f32m1(&za[k][j], res_za, vl);

                vfloat32m1_t vp_k_j_m1_b = __riscv_vlse32_v_f32m1(&zp[k][j-1], 1, vl);
                vfloat32m1_t vq_k_j_m1_b = __riscv_vlse32_v_f32m1(&zq[k][j-1], 1, vl);
                vfloat32m1_t vp_k_j_b    = __riscv_vle32_v_f32m1(&zp[k][j], vl);
                vfloat32m1_t vq_k_j_b    = __riscv_vle32_v_f32m1(&zq[k][j], vl);
                vfloat32m1_t vr_k_j_b    = __riscv_vle32_v_f32m1(&zr[k][j], vl);
                vfloat32m1_t vr_k_m1_j_b = __riscv_vlse32_v_f32m1(&zr[k-1][j], 1, vl);
                vfloat32m1_t vm_k_j_b    = __riscv_vle32_v_f32m1(&zm[k][j], vl);
                vfloat32m1_t vm_k_j_m1_b = __riscv_vlse32_v_f32m1(&zm[k][j-1], 1, vl);

                vfloat32m1_t term1_zb = __riscv_vfadd_vv_f32m1(vp_k_j_m1_b, vq_k_j_m1_b, vl);
                vfloat32m1_t term2_zb = __riscv_vfadd_vv_f32m1(vp_k_j_b, vq_k_j_b, vl);
                vfloat32m1_t diff_zb = __riscv_vfsub_vv_f32m1(term1_zb, term2_zb, vl);
                vfloat32m1_t sum_zr_zb = __riscv_vfadd_vv_f32m1(vr_k_j_b, vr_k_m1_j_b, vl);
                vfloat32m1_t sum_zm_zb = __riscv_vfadd_vv_f32m1(vm_k_j_b, vm_k_j_m1_b, vl);
                vfloat32m1_t res_zb = __riscv_vfdiv_vv_f32m1(__riscv_vfmul_vv_f32m1(diff_zb, sum_zr_zb, vl), sum_zm_zb, vl);
                __riscv_vse32_v_f32m1(&zb[k][j], res_zb, vl);
            }
#endif
            for (; j < jn - 1; ++j) {
                za[k][j] = ( zp[k+1][j-1] + zq[k+1][j-1] - zp[k][j-1] - zq[k][j-1] ) *
                           ( zr[k][j] + zr[k][j-1] ) / ( zm[k][j-1] + zm[k+1][j-1] );
                zb[k][j] = ( zp[k][j-1] + zq[k][j-1] - zp[k][j] - zq[k][j] ) *
                           ( zr[k][j] + zr[k-1][j] ) / ( zm[k][j] + zm[k][j-1] );
            }
        }

        // Loop 2: Update zu and zv
        for (Index_type k = 1; k < kn - 1; ++k) {
            Index_type j = 1;
#if defined(__riscv_vector)
            size_t vlmax = __riscv_vsetvl_e32m1(jn - 2);
            for (; j <= jn - 2; j += vlmax) {
                size_t vl = __riscv_vsetvl_e32m1(jn - 1 - j);

                vfloat32m1_t vza_k_j = __riscv_vle32_v_f32m1(&za[k][j], vl);
                vfloat32m1_t vza_k_j_m1 = __riscv_vlse32_v_f32m1(&za[k][j-1], 1, vl);
                vfloat32m1_t vzb_k_j = __riscv_vle32_v_f32m1(&zb[k][j], vl);
                vfloat32m1_t vzb_k1_j = __riscv_vlse32_v_f32m1(&zb[k+1][j], 1, vl);

                vfloat32m1_t vzz_k_j = __riscv_vle32_v_f32m1(&zz[k][j], vl);
                vfloat32m1_t vzz_k_j1 = __riscv_vlse32_v_f32m1(&zz[k][j+1], 1, vl);
                vfloat32m1_t vzz_k_j_m1 = __riscv_vlse32_v_f32m1(&zz[k][j-1], 1, vl);
                vfloat32m1_t vzz_k_m1_j = __riscv_vlse32_v_f32m1(&zz[k-1][j], 1, vl);
                vfloat32m1_t vzz_k1_j_z = __riscv_vlse32_v_f32m1(&zz[k+1][j], 1, vl);

                vfloat32m1_t vzu_k_j = __riscv_vle32_v_f32m1(&zu[k][j], vl);
                vfloat32m1_t vzv_k_j = __riscv_vle32_v_f32m1(&zv[k][j], vl);

                vfloat32m1_t vr_k_j = __riscv_vle32_v_f32m1(&zr[k][j], vl);
                vfloat32m1_t vr_k_j1 = __riscv_vlse32_v_f32m1(&zr[k][j+1], 1, vl);
                vfloat32m1_t vr_k_j_m1 = __riscv_vlse32_v_f32m1(&zr[k][j-1], 1, vl);
                vfloat32m1_t vr_k_m1_j = __riscv_vlse32_v_f32m1(&zr[k-1][j], 1, vl);
                vfloat32m1_t vr_k1_j_r = __riscv_vlse32_v_f32m1(&zr[k+1][j], 1, vl);

                vfloat32m1_t dzz1 = __riscv_vfsub_vv_f32m1(vzz_k_j, vzz_k_j1, vl);
                vfloat32m1_t dzz2 = __riscv_vfsub_vv_f32m1(vzz_k_j, vzz_k_j_m1, vl);
                vfloat32m1_t dzz3 = __riscv_vfsub_vv_f32m1(vzz_k_j, vzz_k_m1_j, vl);
                vfloat32m1_t dzz4 = __riscv_vfsub_vv_f32m1(vzz_k_j, vzz_k1_j_z, vl);

                vfloat32m1_t term_u = __riscv_vfmul_vv_f32m1(vza_k_j, dzz1, vl);
                term_u = __riscv_vfsub_vv_f32m1(term_u, __riscv_vfmul_vv_f32m1(vza_k_j_m1, dzz2, vl), vl);
                term_u = __riscv_vfsub_vv_f32m1(term_u, __riscv_vfmul_vv_f32m1(vzb_k_j, dzz3, vl), vl);
                term_u = __riscv_vfadd_vv_f32m1(term_u, __riscv_vfmul_vv_f32m1(vzb_k1_j, dzz4, vl), vl);

                vfloat32m1_t dzr1 = __riscv_vfsub_vv_f32m1(vr_k_j, vr_k_j1, vl);
                vfloat32m1_t dzr2 = __riscv_vfsub_vv_f32m1(vr_k_j, vr_k_j_m1, vl);
                vfloat32m1_t dzr3 = __riscv_vfsub_vv_f32m1(vr_k_j, vr_k_m1_j, vl);
                vfloat32m1_t dzr4 = __riscv_vfsub_vv_f32m1(vr_k_j, vr_k1_j_r, vl);

                vfloat32m1_t term_v = __riscv_vfmul_vv_f32m1(vza_k_j, dzr1, vl);
                term_v = __riscv_vfsub_vv_f32m1(term_v, __riscv_vfmul_vv_f32m1(vza_k_j_m1, dzr2, vl), vl);
                term_v = __riscv_vfsub_vv_f32m1(term_v, __riscv_vfmul_vv_f32m1(vzb_k_j, dzr3, vl), vl);
                term_v = __riscv_vfadd_vv_f32m1(term_v, __riscv_vfmul_vv_f32m1(vzb_k1_j, dzr4, vl), vl);

                __riscv_vse32_v_f32m1(&zu[k][j], __riscv_vfadd_vf_f32m1(vzu_k_j, __riscv_vfmul_vf_f32m1(term_u, s, vl), vl), vl);
                __riscv_vse32_v_f32m1(&zv[k][j], __riscv_vfadd_vf_f32m1(vzv_k_j, __riscv_vfmul_vf_f32m1(term_v, s, vl), vl), vl);
            }
#endif
            for (; j < jn - 1; ++j) {
                zu[k][j] += s*( za[k][j]   * ( zz[k][j] - zz[k][j+1] ) -
                                za[k][j-1] * ( zz[k][j] - zz[k][j-1] ) -
                                zb[k][j]   * ( zz[k][j] - zz[k-1][j] ) +
                                zb[k+1][j] * ( zz[k][j] - zz[k+1][j] ) );
                zv[k][j] += s*( za[k][j]   * ( zr[k][j] - zr[k][j+1] ) -
                                za[k][j-1] * ( zr[k][j] - zr[k][j-1] ) -
                                zb[k][j]   * ( zr[k][j] - zr[k-1][j] ) +
                                zb[k+1][j] * ( zr[k][j] - zr[k+1][j] ) );
            }
        }

        // Loop 3: Compute zrout and zzout
        for (Index_type k = 1; k < kn - 1; ++k) {
            Index_type j = 1;
#if defined(__riscv_vector)
            size_t vlmax = __riscv_vsetvl_e32m1(jn - 2);
            for (; j <= jn - 2; j += vlmax) {
                size_t vl = __riscv_vsetvl_e32m1(jn - 1 - j);
                vfloat32m1_t vr = __riscv_vle32_v_f32m1(&zr[k][j], vl);
                vfloat32m1_t vu = __riscv_vle32_v_f32m1(&zu[k][j], vl);
                __riscv_vse32_v_f32m1(&zrout[k][j], __riscv_vfadd_vf_f32m1(vr, __riscv_vfmul_vf_f32m1(vu, t, vl), vl), vl);

                vfloat32m1_t vzz = __riscv_vle32_v_f32m1(&zz[k][j], vl);
                vfloat32m1_t vv = __riscv_vle32_v_f32m1(&zv[k][j], vl);
                __riscv_vse32_v_f32m1(&zzout[k][j], __riscv_vfadd_vf_f32m1(vzz, __riscv_vfmul_vf_f32m1(vv, t, vl), vl), vl);
            }
#endif
            for (; j < jn - 1; ++j) {
                zrout[k][j] = zr[k][j] + t*zu[k][j];
                zzout[k][j] = zz[k][j] + t*zv[k][j];
            }
        }
        dummy(NULL, NULL, NULL, NULL, NULL, t);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_int_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;
    real_t dm22 = 0.7, dm23 = 0.6, dm24 = 0.5, dm25 = 0.4;
    real_t dm26 = 0.3, dm27 = 0.2, dm28 = 0.1, c0 = 1.0/3.0;

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        int i = 0;
        size_t vl;
        // Use float-specific vector types since real_t is float
        while (i < LEN_1D) {
            vl = __riscv_vsetvl_e32m1(LEN_1D - i);

            vfloat32m1_t v_res = __riscv_vle32_v_f32m1((const float*)&px[i + offset * 2], vl);

            vfloat32m1_t v_tmp4 = __riscv_vle32_v_f32m1((const float*)&px[i + offset * 4], vl);
            vfloat32m1_t v_tmp5 = __riscv_vle32_v_f32m1((const float*)&px[i + offset * 5], vl);
            vfloat32m1_t v_sum45 = __riscv_vfadd_vv_f32m1(v_tmp4, v_tmp5, vl);
            v_res = __riscv_vfadd_vv_f32m1(v_res, __riscv_vfmul_vf_f32m1(v_sum45, c0, vl), vl);

            v_res = __riscv_vfmac_vf_f32m1(v_res, dm22, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 6], vl), vl);
            v_res = __riscv_vfmac_vf_f32m1(v_res, dm23, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 7], vl), vl);
            v_res = __riscv_vfmac_vf_f32m1(v_res, dm24, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 8], vl), vl);
            v_res = __riscv_vfmac_vf_f32m1(v_res, dm25, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 9], vl), vl);
            v_res = __riscv_vfmac_vf_f32m1(v_res, dm26, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 10], vl), vl);
            v_res = __riscv_vfmac_vf_f32m1(v_res, dm27, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 11], vl), vl);
            v_res = __riscv_vfmac_vf_f32m1(v_res, dm28, __riscv_vle32_v_f32m1((const float*)&px[i + offset * 12], vl), vl);

            __riscv_vse32_v_f32m1((float*)&px[i], v_res, vl);
            i += vl;
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            px[i] = dm28*px[i + offset * 12] + dm27*px[i + offset * 11] +
                    dm26*px[i + offset * 10] + dm25*px[i + offset *  9] +
                    dm24*px[i + offset *  8] + dm23*px[i + offset *  7] +
                    dm22*px[i + offset *  6] +
                    c0*( px[i + offset *  4] + px[i + offset *  5] ) +
                    px[i + offset *  2];
        }
#endif
        dummy(px, NULL, NULL, NULL, NULL, c0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

real_t lcals_planckian(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        int i = 0;
        size_t vl;
        // Use a larger LMUL to better utilize the vector registers and hide latency
        for (; i < LEN_1D; i += vl) {
            vl = __riscv_vsetvl_e32m8(LEN_1D - i);

            vfloat32m8_t vu = __riscv_vle32_v_f32m8(&u[i], vl);
            vfloat32m8_t vv = __riscv_vle32_v_f32m8(&v[i], vl);

            // y[i] = u[i] / v[i]
