real_t lcals_tridiag_elim(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        int i = 1;
        // Use a larger LMUL (m8) to reduce loop overhead and improve throughput
        // by utilizing more of the vector register file per iteration.
        for (; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e32m8(LEN_1D - i);

            vfloat32m8_t vy = __riscv_vle32_v_f32m8(&y[i], vl);
            vfloat32m8_t vz = __riscv_vle32_v_f32m8(&z[i], vl);
            vfloat32m8_t vxin_prev = __riscv_vle32_v_f32m8(&xin[i-1], vl);

            vfloat32m8_t vres = __riscv_vfsub_vv_f32m8(vy, vxin_prev, vl);
            vres = __riscv_vfmul_vv_f32m8(vz, vres, vl);

            __riscv_vse32_v_f32m8(&xout[i], vres, vl);

            i += vl;
        }
#else
        for (Index_type i = 1; i < LEN_1D; ++i) {
            xout[i] = z[i] * ( y[i] - xin[i-1] );
        }
#endif
        dummy(xout, xin, y, z, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

