real_t stream_dot(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dot_acc = 0.0;

    #if defined(__riscv_vector)
    for (int nl = 0; nl < iterations; nl++) {
        real_t local = 0.0;
        Index_type i = 0;

        size_t vlmax = __riscv_vsetvlmax_e64m1();
        vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(0.0, vlmax);

        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e64m1(LEN_1D - i);
            vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&a[i], vl);
            vfloat64m1_t vb = __riscv_vle64_v_f64m1((const double *)&b[i], vl);
            v_acc = __riscv_vfmacc_vv_f64m1(v_acc, va, vb, vl);
            i += vl;
        }

        vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_acc, v_zero, vlmax);
        local = __riscv_vfmv_f_s_f64m1_f64(v_res);

        dot_acc += local;
        dummy(a, b, NULL, NULL, NULL, local);
    }
    #else
    for (int nl = 0; nl < iterations; nl++) {
        real_t local = 0.0;
        for (Index_type i = 0; i < LEN_1D; ++i) {
            local += a[i] * b[i];
        }
        dot_acc += local;
        dummy(a, b, NULL, NULL, NULL, local);
    }
    #endif

    x[0] = dot_acc / (real_t)((size_t)iterations * (size_t)LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

